gCQ(){return"\u041d\u0435 \u0437\u0430\u043a\u0440\u0438\u0432\u0430\u0439\u0442\u0435 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a \u0434\u043e \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u043d\u044f \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f \u0430\u0431\u043e \u0431\u0435\u0437\u043f\u0435\u0447\u043d\u043e \u043f\u0440\u0438\u0437\u0443\u043f\u0438\u043d\u0456\u0442\u044c \u043f\u0440\u043e\u0446\u0435\u0441."},
gCS(){return"\u041f\u0456\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f\u2026"},
CR(a,b,c){return"\u0412\u0438\u0434\u0430\u043b\u0435\u043d\u043e \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u044c: "+a+" \u0456\u0437 "+b+". \u0417\u0430\u043b\u0438\u0448\u0438\u043b\u043e\u0441\u044f: "+c+"."},
gCN(){return"\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u044f\u0454\u043c\u043e \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441 \u0456 \u0433\u043e\u0442\u0443\u0454\u043c\u043e \u043e\u0447\u0438\u0449\u0435\u043d\u043d\u044f\u2026"},
gCM(){return"\u0412\u0438\u0434\u0430\u043b\u044f\u0454\u043c\u043e \u0456\u0441\u0442\u043e\u0440\u0456\u044e \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u044c \u0456 \u043f\u043e\u0432\u2019\u044f\u0437\u0430\u043d\u0456 \u0434\u0430\u043d\u0456\u2026"},
gCO(){return"\u0412\u0438\u0434\u0430\u043b\u044f\u0454\u043c\u043e \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u0457 \u0442\u0430 \u043e\u043d\u043e\u0432\u043b\u044e\u0454\u043c\u043e \u043b\u0456\u0447\u0438\u043b\u044c\u043d\u0438\u043a\u0438\u2026"},
gCI(){return"\u0412\u0438\u0434\u0430\u043b\u044f\u0454\u043c\u043e \u043b\u0438\u0441\u0442\u0443\u0432\u0430\u043d\u043d\u044f \u0442\u0430 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f\u2026"},
gCL(){return"\u0412\u0438\u0434\u0430\u043b\u044f\u0454\u043c\u043e \u0434\u0430\u043d\u0456 \u0441\u043f\u043e\u0432\u0456\u0449\u0435\u043d\u044c\u2026"},
gCP(){return"\u0412\u0438\u0434\u0430\u043b\u044f\u0454\u043c\u043e \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u0456 \u0437\u0432\u2019\u044f\u0437\u043a\u0438 \u0456\u0437 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f\u043c\u0438\u2026"},
gCJ(){return"\u0412\u0438\u0434\u0430\u043b\u044f\u0454\u043c\u043e \u0444\u0430\u0439\u043b\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u043e\u0433\u043e \u0437\u0430\u043f\u0438\u0441\u0443\u2026"},
gCK(){return"\u0417\u0430\u0432\u0435\u0440\u0448\u0443\u0454\u043c\u043e \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u043e\u0433\u043e \u0437\u0430\u043f\u0438\u0441\u0443\u2026"},
gCE(){return"\u041f\u0440\u0438\u0437\u0443\u043f\u0438\u043d\u0438\u0442\u0438 \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f"},
gCH(){return"\u041f\u0440\u0438\u0437\u0443\u043f\u0438\u043d\u044f\u0454\u043c\u043e\u2026"},
gCF(){return"\u041f\u0456\u0434 \u0447\u0430\u0441 \u043f\u0430\u0443\u0437\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441 \u0456 \u0440\u0435\u0448\u0442\u0430 \u0434\u0430\u043d\u0438\u0445 \u0437\u0431\u0435\u0440\u0456\u0433\u0430\u044e\u0442\u044c\u0441\u044f. \u0423\u0436\u0435 \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u0456 \u0434\u0430\u043d\u0456 \u0432\u0456\u0434\u043d\u043e\u0432\u0438\u0442\u0438 \u043d\u0435\u043c\u043e\u0436\u043b\u0438\u0432\u043e; \u043f\u0440\u043e\u0434\u043e\u0432\u0436\u0438\u0442\u0438 \u043c\u043e\u0436\u043d\u0430 \u043f\u0456\u0437\u043d\u0456\u0448\u0435."},
gCG(){return"\u0412\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u043e\u0433\u043e \u0437\u0430\u043f\u0438\u0441\u0443 \u043f\u0440\u0438\u0437\u0443\u043f\u0438\u043d\u0435\u043d\u043e. \u041f\u0440\u043e\u0434\u043e\u0432\u0436\u0438\u0442\u0438 \u043c\u043e\u0436\u043d\u0430 \u043f\u0456\u0437\u043d\u0456\u0448\u0435 \u0443 \u043f\u0440\u043e\u0444\u0456\u043b\u0456."},
gJU(){return"\u0417\u0430\u043c\u043e\u0432\u043d\u0438\u043a \u0432\u0438\u0431\u0440\u0430\u0432 \u0432\u0430\u0448\u0443 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044e"},
JT(a){return"\u041f\u043e\u0442\u0440\u0456\u0431\u043d\u0435 \u0432\u0430\u0448\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u0434\u043b\u044f \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \xab"+a+"\xbb."},
gJS(){return"\u0412\u0438\u043a\u043e\u043d\u0430\u0432\u0435\u0446\u044c \u043f\u0440\u0438\u0439\u043d\u044f\u0432 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f"},
JR(a){return"\u0417\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \xab"+a+"\xbb \u0442\u0435\u043f\u0435\u0440 \u0443 \u0440\u043e\u0431\u043e\u0442\u0456."},
gK5(){return"\u041f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044f \u0431\u0456\u043b\u044c\u0448\u0435 \u043d\u0435 \u0434\u0456\u0439\u0441\u043d\u0430"},
