K1(a){return"\u0412\u0430\u0448\u0430 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044f \u0434\u043b\u044f \xab"+a+"\xbb \u0431\u0456\u043b\u044c\u0448\u0435 \u043d\u0435 \u0430\u043a\u0442\u0438\u0432\u043d\u0430."},
gRI(){return"\u041e\u0447\u0456\u043a\u0443\u0454 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0446\u044f"},
gRz(){return"\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u0438 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044e"},
gRB(){return"\u041d\u0430\u0434\u0456\u0441\u043b\u0430\u0442\u0438 \u0446\u044c\u043e\u043c\u0443 \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0446\u044e \u0437\u0430\u043f\u0438\u0442 \u043d\u0430 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f?"},
gRA(){return"\u0417\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0437\u0430\u043b\u0438\u0448\u0430\u0442\u0438\u043c\u0435\u0442\u044c\u0441\u044f \u043e\u043f\u0443\u0431\u043b\u0456\u043a\u043e\u0432\u0430\u043d\u0438\u043c \u0434\u043e \u0437\u0433\u043e\u0434\u0438 \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0446\u044f. \u041f\u0456\u0434 \u0447\u0430\u0441 \u043e\u0447\u0456\u043a\u0443\u0432\u0430\u043d\u043d\u044f \u0437\u0430\u043f\u0438\u0442 \u043c\u043e\u0436\u043d\u0430 \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438."},
gRD(){return"\u0417\u0430\u043f\u0438\u0442 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0434\u0456\u0441\u043b\u0430\u043d\u043e \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0446\u044e."},
gRC(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u043d\u0430\u0434\u0456\u0441\u043b\u0430\u0442\u0438 \u0437\u0430\u043f\u0438\u0442. \u0421\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437."},
gQP(){return"\u0421\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438 \u0437\u0430\u043f\u0438\u0442 \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0446\u044e"},
gQR(){return"\u0421\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438 \u0437\u0430\u043f\u0438\u0442 \u0446\u044c\u043e\u043c\u0443 \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0446\u044e?"},
gQQ(){return"\u0417\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0437\u0430\u043b\u0438\u0448\u0438\u0442\u044c\u0441\u044f \u043e\u043f\u0443\u0431\u043b\u0456\u043a\u043e\u0432\u0430\u043d\u0438\u043c, \u0430 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044e \u0437\u043d\u043e\u0432\u0443 \u043c\u043e\u0436\u043d\u0430 \u0431\u0443\u0434\u0435 \u0432\u0438\u0431\u0440\u0430\u0442\u0438."},
gQT(){return"\u0417\u0430\u043f\u0438\u0442 \u0441\u043a\u0430\u0441\u043e\u0432\u0430\u043d\u043e."},
